package com.smartmerchant.saas.trade.infrastructure;
import com.smartmerchant.saas.trade.application.MemberGateway;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class HttpMemberGateway implements MemberGateway {private final RestClient client;private final String key;public HttpMemberGateway(@Value("${saas.trade.member-service-url}")String url,@Value("${saas.security.internal-signing-key}")String key){this.client=RestClient.builder().baseUrl(url).build();this.key=key;}public BenefitQuote quote(BenefitRequest r){return post("quote",r);}public BenefitQuote freeze(BenefitRequest r){return post("freeze",r);}public void confirm(BenefitRequest r){call("confirm",r);}public void release(BenefitRequest r){call("release",r);}public void refund(BenefitRequest r){call("refund",r);}private void call(String op,BenefitRequest r){client.post().uri("/internal/v1/member/benefits/"+op).header("X-Internal-Key",key).body(r).retrieve().toBodilessEntity();}private BenefitQuote post(String op,BenefitRequest r){return client.post().uri("/internal/v1/member/benefits/"+op).header("X-Internal-Key",key).body(r).retrieve().body(BenefitQuote.class);}}
